const LoadingIntro = ( props : { hide ?: boolean }) => {

    const initialProps : any = {
        initial : { opacity : 0 }, animate : { opacity : 1}, transition : { delay : 0.5, duration : 0.5 }
    }
    
    if( props.hide ) return <></>
    return (<>

        <motion.div {...{
            initial : { display : 'relative' }, 
            animate : { display : 'none' }, 
            transition : { delay : 4.5, duration : 0.1 }
        }}>
            <motion.div {...{
                initial : { opacity : 1, position : 'fixed', top : 0, left : 0, width : '100vw', height : '100vh' }, 
                animate : { opacity : 0, height : 0 }, 
                transition : { delay : 3.5, duration : 1.0 }
            }}>
                <div style={{ backgroundColor : 'white', width : '100vw', height : '100vh'}}>
                    <motion.div {...initialProps}>
                        <Center>
                            <GridRow height="100vh">
                                <motion.div {...{
                                        initial : { transform : `rotate(0deg)` }, 
                                        animate : { transform : `rotate(360deg)` }, 
                                        transition : { delay : 1.5, duration : 0.4 }
                                    }}>
                                    
                                    <motion.div {...{
                                        initial : { marginTop : `-300px` }, 
                                        animate : { marginTop : `50px` }, 
                                        transition : { delay : 1, duration : 0.5 }
                                    }}>
                                        <img src={logoSM}/>
                                    </motion.div>
                                    <motion.div {...{
                                        initial : { marginTop : `2000px` }, 
                                        animate : { marginTop : `-50px` }, 
                                        transition : { delay : 1, duration : 0.5 }
                                    }}>
                                        <img src={logoSM}/>
                                    </motion.div> 
                                </motion.div>
                                <SpacerV h={10}/>
                                <motion.div {...{
                                    initial : { opacity : 0 }, 
                                    animate : { opacity : 1 }, 
                                    transition : { delay : 2.5, duration : 0.5 }
                                }}>
                                    <img src={logoSM}/>
                                </motion.div>
                            </GridRow>
                        </Center>
                    </motion.div>
                </div>
            </motion.div>
        </motion.div>
        
    </>)
}


